insert into public.journey_content
(day_number,phase_key,cadence,cadence_index,title,summary,prompt,choices,reflection_prompt,actions,tap21_domains,published)
values
(1,'stabilize','daily',null,'Start Here: Safety & Support','Today is about getting a little steadier. You do not need to solve your whole recovery at once.','What would help you feel a little safer or steadier today?','["A safe place", "Someone I trust", "Food / water", "Rest", "Distance from alcohol / drugs", "A meeting or recovery support", "Medical / professional help", "I''m not sure yet"]'::jsonb,'What would make today a little steadier?','["Call or text someone supportive", "Eat and hydrate", "Rest somewhere safe", "Attend a meeting", "Create distance from alcohol / drugs", "Ask for professional help", "Take one hour at a time"]'::jsonb,ARRAY['Assessment','Counseling','Client Education']::text[],true),
(2,'stabilize','daily',null,'Understanding Where I Am','Notice what feels true, what could use a little care, and one manageable next step.','What parts of life could use a little more care right now?','["Physical health", "Mental / emotional health", "Family", "Relationships", "Work", "School", "Money", "Housing", "Legal concerns", "Spiritual life", "Self-respect", "I''m not sure yet"]'::jsonb,'What would make today a little steadier?','["Call a support person", "Attend a meeting", "Eat and hydrate", "Rest", "Avoid a high-risk person / place", "Make a treatment / counseling appointment", "Take one small healthy step"]'::jsonb,ARRAY['Assessment','Counseling','Client Education']::text[],true),
(3,'stabilize','daily',null,'What Do I Need Today?','Some things need attention now. Other things can wait. Today is about telling the difference.','What needs your attention first today?','["My body", "Safety", "Cravings", "Emotions", "Support", "Sleep", "A responsibility", "Something else"]'::jsonb,'What would make today a little steadier?','["Handle one urgent need", "Ask someone for help", "Eat / hydrate", "Rest", "Use a coping tool", "Make one necessary call", "Let one non-urgent thing wait"]'::jsonb,ARRAY['Assessment','Counseling','Client Education']::text[],true),
(4,'stabilize','daily',null,'Understanding Cravings','A craving can feel urgent without being a command. It can rise, change, and pass.','What do you notice most when a craving shows up?','["Thoughts about using", "Restlessness", "Anxiety", "Body tension", "Irritability", "A strong memory", "Wanting relief", "I''m not sure"]'::jsonb,'What would make today a little steadier?','["Wait 10 minutes before acting", "Change my environment", "Call someone", "Use grounding", "Eat / hydrate", "Go to a meeting", "Remove access if I safely can"]'::jsonb,ARRAY['Assessment','Counseling','Client Education']::text[],true),
(5,'stabilize','daily',null,'Recognizing Triggers','Triggers are information. Noticing one gives you more choice about what happens next.','What kind of trigger stands out most right now?','["A person", "A place", "Stress", "Conflict", "Loneliness", "Money", "Celebration", "Boredom", "A memory", "Seeing substances"]'::jsonb,'What would make today a little steadier?','["Avoid one trigger today", "Plan an exit", "Tell a support person", "Use a coping tool", "Change one routine", "Write down what happened"]'::jsonb,ARRAY['Assessment','Counseling','Client Education']::text[],true),
(6,'stabilize','daily',null,'HALT: Check the Basics','Sometimes recovery gets harder when a basic need has been ignored.','Which need feels loudest today?','["Hungry", "Angry", "Lonely", "Tired", "More than one", "None of these", "I''m not sure"]'::jsonb,'What would make today a little steadier?','["Eat something nourishing", "Rest", "Talk to someone", "Cool down before responding", "Take a walk", "Slow the day down"]'::jsonb,ARRAY['Assessment','Counseling','Client Education']::text[],true),
(7,'stabilize','daily',null,'Week 1 Review: What Helped?','You made it through your first week. You do not need a perfect score—just notice what helped.','What supported you most this week?','["A person", "A meeting", "Routine", "Avoiding triggers", "Rest", "Prayer / spirituality", "Professional support", "A coping skill", "Simply getting through each day"]'::jsonb,'What would make today a little steadier?','["Keep one thing that worked", "Strengthen one support", "Adjust one routine", "Ask for more help", "Celebrate the week quietly"]'::jsonb,ARRAY['Assessment','Counseling','Client Education']::text[],true),
(8,'stabilize','daily',null,'Building a Simple Routine','A little predictability can make recovery feel less chaotic.','What part of your day could use more structure?','["Morning", "Meals", "Work / school", "Afternoon", "Evening", "Sleep", "Medication / appointments", "Recovery time"]'::jsonb,'What would make today a little steadier?','["Choose a consistent wake time", "Plan meals", "Schedule recovery time", "Set one reminder", "Create a calmer evening", "Prepare tomorrow tonight"]'::jsonb,ARRAY['Assessment','Counseling','Client Education']::text[],true),
(9,'stabilize','daily',null,'People Who Support Recovery','Not every relationship supports the direction you are going. Today, notice who helps you move toward recovery.','Who feels safest or most supportive right now?','["Family member", "Friend", "Sponsor / peer", "Counselor", "Recovery group", "Faith community", "Coworker", "No one yet"]'::jsonb,'What would make today a little steadier?','["Reach out to one safe person", "Save a support number", "Attend a group", "Tell someone what I need", "Identify one relationship to limit"]'::jsonb,ARRAY['Assessment','Counseling','Client Education']::text[],true),
(10,'stabilize','daily',null,'Asking for Help','Asking clearly can make it easier for people to support you.','What kind of help would make today easier?','["Someone to listen", "A ride", "A meeting", "Help with food / basics", "Professional support", "Company", "Advice", "Accountability"]'::jsonb,'What would make today a little steadier?','["Make one specific request", "Call a support person", "Ask for a meeting ride", "Schedule professional support", "Tell someone I need company"]'::jsonb,ARRAY['Assessment','Counseling','Client Education']::text[],true),
(11,'stabilize','daily',null,'Changing the Environment','You do not have to rely on willpower alone. Your surroundings can make recovery easier or harder.','What could you change around you today?','["Remove substances", "Avoid a location", "Limit contact with someone", "Change my route", "Stay with supportive people", "Clean / reset my space", "Plan where I will go"]'::jsonb,'What would make today a little steadier?','["Remove one cue", "Avoid one high-risk place", "Change one routine", "Prepare a safe place", "Tell someone my plan"]'::jsonb,ARRAY['Assessment','Counseling','Client Education']::text[],true),
(12,'stabilize','daily',null,'Coping Without Using','Coping is not about feeling good immediately. It is about getting through the moment safely.','What might help you ride out discomfort for 10 minutes?','["Walk", "Music", "Shower", "Breathing", "Call someone", "Meeting", "Write", "Eat / drink water", "Rest", "Prayer / meditation"]'::jsonb,'What would make today a little steadier?','["Try one coping tool for 10 minutes", "Use a second tool if needed", "Contact support", "Move to a safer environment"]'::jsonb,ARRAY['Assessment','Counseling','Client Education']::text[],true),
(13,'stabilize','daily',null,'Sleep, Rest & Recovery','Exhaustion can make everything feel harder. Rest is part of recovery, not a reward for doing enough.','What would help your body settle tonight?','["Less screen time", "A regular bedtime", "Quiet", "Food / hydration", "A shower", "Medication as prescribed", "Less caffeine", "A calmer room"]'::jsonb,'What would make today a little steadier?','["Choose one bedtime support", "Prepare the room", "Set a wind-down time", "Ask for medical guidance if sleep is persistently difficult"]'::jsonb,ARRAY['Assessment','Counseling','Client Education']::text[],true),
(14,'stabilize','daily',null,'Week 2 Review: My Foundation','Two weeks in, notice what is beginning to hold you up.','What feels a little stronger than it did at the start?','["Routine", "Support", "Sleep", "Coping", "Honesty", "Avoiding triggers", "Hope", "Nothing yet", "I''m not sure"]'::jsonb,'What would make today a little steadier?','["Keep one helpful habit", "Strengthen one weak area", "Ask for more support", "Give myself credit for continuing"]'::jsonb,ARRAY['Assessment','Counseling','Client Education']::text[],true),
(15,'stabilize','daily',null,'Thoughts Are Not Commands','A thought can be loud without being something you have to follow.','What kind of thought tends to pull you toward old behavior?','["I can''t do this", "Just once won''t hurt", "I deserve relief", "No one cares", "I''ve already messed up", "I miss using", "I feel trapped", "Something else"]'::jsonb,'What would make today a little steadier?','["Name the thought", "Wait before acting", "Replace it with a more balanced thought", "Tell someone", "Change my environment"]'::jsonb,ARRAY['Assessment','Counseling','Client Education']::text[],true),
(16,'stabilize','daily',null,'Emotions Without Escape','Feelings can be uncomfortable without being dangerous. You can learn to stay with them safely.','What feeling is strongest underneath the urge to escape?','["Fear", "Sadness", "Anger", "Shame", "Loneliness", "Boredom", "Stress", "Grief", "I don''t know"]'::jsonb,'What would make today a little steadier?','["Name the feeling", "Breathe and stay present", "Talk to someone", "Write it down", "Move my body", "Use a grounding tool"]'::jsonb,ARRAY['Assessment','Counseling','Client Education']::text[],true),
(17,'stabilize','daily',null,'Stress & Overload','When everything feels urgent, recovery can get buried. Today, make the load smaller.','What is creating the most pressure right now?','["Work", "Family", "Money", "Legal issues", "Health", "Too many tasks", "Conflict", "Uncertainty"]'::jsonb,'What would make today a little steadier?','["Postpone one non-urgent task", "Ask for help", "Do one task only", "Take a short break", "Write a short priority list"]'::jsonb,ARRAY['Assessment','Counseling','Client Education']::text[],true),
(18,'stabilize','daily',null,'Anger & Recovery','Anger can carry important information. The goal is to create space between the feeling and the action.','What does your anger seem connected to?','["Feeling disrespected", "Fear", "Stress", "A boundary crossed", "Guilt", "Frustration", "Feeling powerless", "I''m not sure"]'::jsonb,'What would make today a little steadier?','["Pause before responding", "Leave the situation briefly", "Talk to someone safe", "Write before speaking", "Use breathing / grounding"]'::jsonb,ARRAY['Assessment','Counseling','Client Education']::text[],true),
(19,'stabilize','daily',null,'Loneliness & Connection','Isolation can make recovery harder. Connection can be small and still count.','What kind of connection would feel most manageable today?','["Text someone", "Phone call", "Meeting", "Sit with family", "Online recovery group", "Faith community", "Professional support", "Just be around safe people"]'::jsonb,'What would make today a little steadier?','["Make one connection", "Attend one group", "Tell someone I''m lonely", "Spend time in a safe public place"]'::jsonb,ARRAY['Assessment','Counseling','Client Education']::text[],true),
(20,'stabilize','daily',null,'Boundaries for Early Recovery','A boundary is one way of protecting what you are building.','Where might you need a little more space or a clearer limit?','["A person who uses", "Family conflict", "Social events", "Work demands", "Money requests", "Phone / social media", "A relationship", "My own schedule"]'::jsonb,'What would make today a little steadier?','["Say no once", "Leave early", "Limit contact", "Ask for space", "Tell someone my boundary", "Plan an exit"]'::jsonb,ARRAY['Assessment','Counseling','Client Education']::text[],true),
(21,'stabilize','daily',null,'Week 3 Review: Warning Signs','Warning signs are easier to respond to when you recognize them early.','What sign tells you recovery needs more attention?','["Isolating", "Skipping support", "Poor sleep", "Romanticizing use", "More anger", "Stopping routines", "Being around substances", "Keeping secrets", "Feeling hopeless"]'::jsonb,'What would make today a little steadier?','["Tell someone", "Return to a routine", "Attend support", "Reduce risk", "Schedule professional help", "Use my safety plan"]'::jsonb,ARRAY['Assessment','Counseling','Client Education']::text[],true),
(22,'stabilize','daily',null,'Meetings & Peer Support','Recovery support does not have to look the same for everyone. Explore what helps you feel connected.','What kind of peer support feels most useful?','["12-Step", "SMART / skills-based", "Faith-based", "Secular recovery", "Online meeting", "In-person meeting", "One-to-one peer support", "I''m still exploring"]'::jsonb,'What would make today a little steadier?','["Try one meeting", "Save a meeting option", "Talk to a peer", "Try a different format", "Ask someone what helped them"]'::jsonb,ARRAY['Assessment','Counseling','Client Education']::text[],true),
(23,'stabilize','daily',null,'Professional Support','Self-help is valuable, and some things deserve professional care too.','Is there an area where more support could help?','["Mental health", "Medication", "Withdrawal / medical concerns", "Trauma", "Relationships", "Legal / social services", "Housing", "Work", "I''m okay for now"]'::jsonb,'What would make today a little steadier?','["Schedule an appointment", "Ask for a referral", "Write down questions", "Call a program", "Talk to my current provider"]'::jsonb,ARRAY['Assessment','Counseling','Client Education']::text[],true),
(24,'stabilize','daily',null,'Repair Starts With Stability','You do not have to fix every relationship immediately. Stability comes first.','What relationship needs patience rather than rushing?','["Partner", "Parent", "Child", "Sibling", "Friend", "Coworker", "Myself", "I''m not ready to focus on relationships"]'::jsonb,'What would make today a little steadier?','["Avoid making a promise I can''t keep", "Respect a boundary", "Listen more than I explain", "Give someone space", "Focus on consistent actions"]'::jsonb,ARRAY['Assessment','Counseling','Client Education']::text[],true),
(25,'stabilize','daily',null,'Handling High-Risk Moments','Planning before a difficult situation gives you more options when it arrives.','What high-risk situation might be coming up?','["Weekend", "Payday", "Party", "Family event", "Conflict", "Being alone", "Seeing someone I used with", "Stressful appointment", "Travel"]'::jsonb,'What would make today a little steadier?','["Make an exit plan", "Bring support", "Avoid the event", "Arrange transportation", "Call someone before and after", "Plan a safe alternative"]'::jsonb,ARRAY['Assessment','Counseling','Client Education']::text[],true),
(26,'stabilize','daily',null,'What Gives Me Hope?','Hope does not have to be huge. It can simply be a reason to keep going today.','What do you want more of in your life?','["Peace", "Family", "Health", "Trust", "Freedom", "Stability", "Purpose", "Work / education", "Self-respect", "Joy"]'::jsonb,'What would make today a little steadier?','["Do one thing that supports that future", "Write down why recovery matters", "Tell someone what I hope for", "Protect today''s recovery"]'::jsonb,ARRAY['Assessment','Counseling','Client Education']::text[],true),
(27,'stabilize','daily',null,'Values: Who Do I Want to Be?','Recovery can become more than avoiding substances. It can help your choices line up with who you want to be.','What value feels important to you now?','["Honesty", "Family", "Responsibility", "Faith", "Kindness", "Courage", "Health", "Freedom", "Growth", "Service", "Respect"]'::jsonb,'What would make today a little steadier?','["Choose one action that matches my value", "Pause before a choice and ask what fits my values", "Write down what this value means to me"]'::jsonb,ARRAY['Assessment','Counseling','Client Education']::text[],true),
(28,'stabilize','daily',null,'Week 4 Review: What Is Changing?','Change can be quiet. Look for differences in how you respond, not just how you feel.','What seems different from Day 1?','["I ask for help sooner", "I recognize triggers", "I have more routine", "I cope differently", "I am more honest", "I feel more hopeful", "My cravings changed", "Nothing feels different yet"]'::jsonb,'What would make today a little steadier?','["Keep one change going", "Strengthen one area", "Review what worked", "Ask for help with what is still hard"]'::jsonb,ARRAY['Assessment','Counseling','Client Education']::text[],true),
(29,'stabilize','daily',null,'My Early Warning Plan','A plan is easier to use when it is simple enough to remember.','What is one early sign that tells you to act sooner?','["Isolation", "Skipping meetings / support", "Poor sleep", "More cravings", "Thinking about old people / places", "More conflict", "Stopping routines", "Keeping secrets", "Feeling hopeless"]'::jsonb,'What would make today a little steadier?','["Contact support", "Go to a meeting", "Reduce access", "Return to routine", "Ask for professional help", "Leave a risky environment"]'::jsonb,ARRAY['Assessment','Counseling','Client Education']::text[],true),
(30,'stabilize','daily',null,'30-Day Review: My Next Step','Thirty days is a place to look back, not a finish line. Notice what you have learned about your recovery.','What has mattered most in your first month?','["Support", "Routine", "Honesty", "Coping skills", "Avoiding triggers", "Professional care", "Faith / spirituality", "Learning about myself", "Simply not giving up"]'::jsonb,'What would make today a little steadier?','["Choose one priority for Phase 2", "Keep one strong habit", "Ask for help with one unfinished need", "Mark the milestone", "Review my first-month Recovery Picture"]'::jsonb,ARRAY['Assessment','Counseling','Client Education']::text[],true),
(31,'build','daily',null,'Build on What Worked','You already have proof that some things help. Today is about strengthening what is working.','What helped you most during your first month?','["Routine", "Support", "Meetings", "Avoiding triggers", "Rest", "Professional care", "Faith / spirituality", "Coping tools", "Honesty"]'::jsonb,'What do you want to remember about what helps?','["Repeat one thing that worked", "Strengthen one support", "Protect one routine", "Schedule recovery time", "Ask for help sooner"]'::jsonb,ARRAY['Counseling','Client Education','Treatment Planning']::text[],true),
(32,'build','daily',null,'Know Your Trigger Pattern','Triggers often repeat. Seeing the pattern gives you more choice.','Which trigger shows up most often for you?','["Stress", "Conflict", "Loneliness", "Boredom", "Payday", "Certain people", "Certain places", "Celebrations", "Memories", "Feeling rejected"]'::jsonb,'What do you want to remember about what helps?','["Write down the pattern", "Avoid one trigger today", "Tell someone about it", "Make an exit plan", "Use a coping tool early"]'::jsonb,ARRAY['Counseling','Client Education','Treatment Planning']::text[],true),
(33,'build','daily',null,'Pause Before the Urge Grows','The earlier you notice an urge, the more options you have.','What is your earliest sign that a craving is starting?','["Thinking about using", "Body tension", "Restlessness", "Irritability", "Romanticizing the past", "Isolating", "Looking for an excuse", "Contacting risky people"]'::jsonb,'What do you want to remember about what helps?','["Pause for 10 minutes", "Change locations", "Call someone", "Use grounding", "Eat or hydrate", "Go to a meeting"]'::jsonb,ARRAY['Counseling','Client Education','Treatment Planning']::text[],true),
(34,'build','daily',null,'Build a Coping Menu','One coping tool will not fit every situation. Recovery gets stronger when you have options.','Which type of coping helps you most?','["Movement", "Talking", "Quiet", "Music", "Writing", "Breathing", "Prayer / meditation", "Meetings", "Being outdoors"]'::jsonb,'What do you want to remember about what helps?','["Use one tool before stress gets high", "Try a new coping tool", "Save three go-to options", "Ask someone what works for them"]'::jsonb,ARRAY['Counseling','Client Education','Treatment Planning']::text[],true),
(35,'build','daily',null,'Support Before Crisis','Support works best when you use it before everything feels urgent.','When are you most likely to pull away from support?','["When ashamed", "When angry", "When tired", "When overwhelmed", "After conflict", "When cravings rise", "When I think I should handle it alone"]'::jsonb,'What do you want to remember about what helps?','["Reach out before the day gets hard", "Schedule a check-in", "Attend support even if I feel okay", "Tell someone when I am pulling away"]'::jsonb,ARRAY['Counseling','Client Education','Treatment Planning']::text[],true),
(36,'build','daily',null,'Healthy Distraction','Sometimes the safest choice is simply to get through the next hour without feeding the urge.','What kind of healthy distraction works for you?','["TV / movie", "Walk", "Cleaning", "Cooking", "Music", "Game", "Reading", "Calling someone", "Errand"]'::jsonb,'What do you want to remember about what helps?','["Plan one distraction", "Keep it simple", "Use it for 20 minutes", "Pair it with support if cravings stay high"]'::jsonb,ARRAY['Counseling','Client Education','Treatment Planning']::text[],true),
(37,'build','daily',null,'Week 5 Review: What Is Becoming Easier?','Progress can show up as small changes in how you respond.','What feels a little easier now?','["Asking for help", "Recognizing triggers", "Getting through cravings", "Sleeping", "Following routine", "Saying no", "Being honest", "Nothing yet"]'::jsonb,'What do you want to remember about what helps?','["Keep one helpful habit", "Notice one improvement", "Ask for help with what is still hard", "Give yourself credit for continuing"]'::jsonb,ARRAY['Counseling','Client Education','Treatment Planning']::text[],true),
(38,'build','daily',null,'Handling Boredom','Boredom can make old habits look more appealing than they really were.','When boredom hits, what do you usually want most?','["Stimulation", "People", "Escape", "Purpose", "Something to do", "Rest", "Excitement"]'::jsonb,'What do you want to remember about what helps?','["Plan one healthy activity", "Leave the house safely", "Call someone", "Start a small project", "Try something new"]'::jsonb,ARRAY['Counseling','Client Education','Treatment Planning']::text[],true),
(39,'build','daily',null,'Handling Shame','Shame often says hide. Recovery usually asks for safe honesty instead.','What does shame make you want to do?','["Hide", "Avoid people", "Give up", "Use", "Defend myself", "Over-apologize", "Stay silent"]'::jsonb,'What do you want to remember about what helps?','["Tell one safe person the truth", "Write without judging yourself", "Separate behavior from identity", "Ask for support"]'::jsonb,ARRAY['Counseling','Client Education','Treatment Planning']::text[],true),
(40,'build','daily',null,'Handling Guilt','Guilt can point toward repair, but you do not have to repair everything at once.','What kind of repair feels appropriate now?','["Take responsibility", "Stop repeating a behavior", "Respect a boundary", "Make a small correction", "Wait until I am more stable", "Ask for guidance"]'::jsonb,'What do you want to remember about what helps?','["Choose one responsible action", "Avoid making promises you cannot keep", "Practice consistency", "Ask before making amends"]'::jsonb,ARRAY['Counseling','Client Education','Treatment Planning']::text[],true),
(41,'build','daily',null,'What Is in My Control?','Recovery gets easier when you stop spending energy on things you cannot control.','What is actually in your control today?','["My next choice", "Who I call", "Where I go", "What I say", "My routine", "My boundaries", "How I respond"]'::jsonb,'What do you want to remember about what helps?','["Choose one controllable action", "Let one uncontrollable thing sit", "Ask for help with one decision"]'::jsonb,ARRAY['Counseling','Client Education','Treatment Planning']::text[],true),
(42,'build','daily',null,'Build Emotional Awareness','Naming emotions can make them less confusing and easier to respond to.','Which feeling has been showing up most lately?','["Anxiety", "Anger", "Sadness", "Fear", "Loneliness", "Shame", "Hope", "Relief", "Numbness"]'::jsonb,'What do you want to remember about what helps?','["Name it without fixing it", "Notice where you feel it in your body", "Talk to someone", "Use one coping tool"]'::jsonb,ARRAY['Counseling','Client Education','Treatment Planning']::text[],true),
(43,'build','daily',null,'Managing Triggers','Triggers are not failures. They are signals that help you plan.','Which trigger needs the most attention this week?','["People", "Places", "Feelings", "Stress", "Money", "Relationships", "Celebrations", "Memories", "Boredom"]'::jsonb,'What do you want to remember about what helps?','["Plan around one trigger", "Reduce exposure", "Use support earlier", "Prepare an exit", "Practice one coping response"]'::jsonb,ARRAY['Counseling','Client Education','Treatment Planning']::text[],true),
(44,'build','daily',null,'High-Risk People','Some relationships can pull recovery backward even when the person matters to you.','What makes a person high-risk for your recovery?','["They use around me", "They pressure me", "They minimize recovery", "We have a using history", "They create chaos", "I struggle to say no"]'::jsonb,'What do you want to remember about what helps?','["Limit contact", "Meet only in safe settings", "Bring support", "Say no clearly", "Take a break from contact"]'::jsonb,ARRAY['Counseling','Client Education','Treatment Planning']::text[],true),
(45,'build','daily',null,'High-Risk Places','Places can carry powerful memories and routines.','Which type of place feels most risky?','["Bars / clubs", "Certain neighborhoods", "Someone''s home", "Stores", "Workplace", "Parties", "Old hangouts"]'::jsonb,'What do you want to remember about what helps?','["Avoid one place", "Change your route", "Go with support", "Plan an exit", "Choose a safer alternative"]'::jsonb,ARRAY['Counseling','Client Education','Treatment Planning']::text[],true),
(46,'build','daily',null,'Stress Without Escape','Stress can be real without requiring an old solution.','What kind of stress is most present today?','["Family", "Work", "Money", "Health", "Legal concerns", "Housing", "Relationships", "Too much to do"]'::jsonb,'What do you want to remember about what helps?','["Reduce one demand", "Ask for help", "Do one task only", "Take a short reset", "Use a calming tool"]'::jsonb,ARRAY['Counseling','Client Education','Treatment Planning']::text[],true),
(47,'build','daily',null,'Protecting Sleep','Sleep affects mood, judgment, cravings, and patience.','What is getting in the way of rest?','["Racing thoughts", "Phone / screens", "Noise", "Caffeine", "Stress", "Irregular routine", "Cravings", "Physical discomfort"]'::jsonb,'What do you want to remember about what helps?','["Change one bedtime habit", "Set a wind-down time", "Reduce late caffeine", "Ask for medical guidance if needed"]'::jsonb,ARRAY['Counseling','Client Education','Treatment Planning']::text[],true),
(48,'build','daily',null,'Food, Hydration & Recovery','Your body can make recovery feel harder when basic needs are ignored.','What basic need needs attention today?','["Water", "A real meal", "Regular meals", "Less caffeine", "Rest", "Medication as prescribed", "Medical care"]'::jsonb,'What do you want to remember about what helps?','["Drink water", "Eat something nourishing", "Plan the next meal", "Slow down caffeine", "Follow prescribed care"]'::jsonb,ARRAY['Counseling','Client Education','Treatment Planning']::text[],true),
(49,'build','daily',null,'Week 7 Review: My Risk & Protection','Recovery is strengthened by knowing both what raises risk and what protects you.','What protects you most right now?','["Support", "Routine", "Meetings", "Faith / spirituality", "Professional care", "Distance from substances", "Sleep", "Purpose"]'::jsonb,'What do you want to remember about what helps?','["Strengthen one protective factor", "Reduce one risk", "Tell someone what helps you"]'::jsonb,ARRAY['Counseling','Client Education','Treatment Planning']::text[],true),
(50,'build','daily',null,'Handling Celebrations','Celebrations can be joyful and still require a recovery plan.','What would help you feel safe at a celebration?','["Bring support", "Drive myself", "Leave early", "Bring my own drink", "Skip it", "Tell someone my plan", "Attend a recovery event instead"]'::jsonb,'What do you want to remember about what helps?','["Choose your plan before the event", "Set an exit time", "Tell someone your boundary"]'::jsonb,ARRAY['Counseling','Client Education','Treatment Planning']::text[],true),
(51,'build','daily',null,'Handling Conflict','Conflict does not have to become a reason to abandon recovery.','What usually happens when conflict starts?','["I shut down", "I yell", "I leave", "I want to use", "I keep arguing", "I feel rejected", "I become impulsive"]'::jsonb,'What do you want to remember about what helps?','["Pause before responding", "Leave briefly", "Use one calm sentence", "Call support", "Return later if needed"]'::jsonb,ARRAY['Counseling','Client Education','Treatment Planning']::text[],true),
(52,'build','daily',null,'Healthy Boundaries','Boundaries protect your recovery and your relationships.','Which boundary feels most important now?','["No substances around me", "No money lending", "No yelling", "No surprise visits", "Limit certain calls", "Leave if pressured", "Protect recovery time"]'::jsonb,'What do you want to remember about what helps?','["State one boundary", "Follow through once", "Ask for support enforcing it"]'::jsonb,ARRAY['Counseling','Client Education','Treatment Planning']::text[],true),
(53,'build','daily',null,'Rebuilding Trust Slowly','Trust usually returns through repeated actions, not one conversation.','What builds trust most right now?','["Showing up", "Honesty", "Keeping promises", "Respecting boundaries", "Consistency", "Listening", "Giving people time"]'::jsonb,'What do you want to remember about what helps?','["Choose one trustworthy action", "Keep one promise", "Avoid over-explaining", "Let consistency speak"]'::jsonb,ARRAY['Counseling','Client Education','Treatment Planning']::text[],true),
(54,'build','daily',null,'Money as a Trigger','Money can create risk through stress, access, or old routines.','What money situation feels most risky?','["Payday", "Cash on hand", "Debt", "Borrowing", "Giving money away", "Online spending", "Arguments about money"]'::jsonb,'What do you want to remember about what helps?','["Plan payday", "Limit cash", "Pay one priority", "Ask for accountability", "Avoid a risky purchase"]'::jsonb,ARRAY['Counseling','Client Education','Treatment Planning']::text[],true),
(55,'build','daily',null,'Work & Recovery','Work can provide structure and stress at the same time.','What part of work affects recovery most?','["Stress", "Coworkers", "Schedule", "Exhaustion", "Money", "Conflict", "Too much free time", "Job search"]'::jsonb,'What do you want to remember about what helps?','["Protect recovery time", "Take a break", "Ask for support", "Set one boundary", "Do one work task"]'::jsonb,ARRAY['Counseling','Client Education','Treatment Planning']::text[],true),
(56,'build','daily',null,'Week 8 Review: What Protects Me?','By now, you are building a clearer picture of what helps recovery stay strong.','Which protection do you want to strengthen?','["Support", "Routine", "Boundaries", "Coping", "Sleep", "Meetings", "Professional care", "Faith / spirituality"]'::jsonb,'What do you want to remember about what helps?','["Choose one protection to strengthen", "Schedule it", "Tell someone your plan", "Review what worked"]'::jsonb,ARRAY['Counseling','Client Education','Treatment Planning']::text[],true),
(57,'build','daily',null,'Plan for the Weekend','Unstructured time can raise risk. A simple plan can lower it.','What part of the weekend needs a plan?','["Evening", "Being alone", "Social events", "Payday", "Family", "Boredom", "Transportation", "Sleep schedule"]'::jsonb,'What do you want to remember about what helps?','["Plan one safe activity", "Schedule support", "Avoid one risk", "Prepare transportation", "Set a check-in"]'::jsonb,ARRAY['Counseling','Client Education','Treatment Planning']::text[],true),
(58,'build','daily',null,'Plan for a Difficult Conversation','Difficult conversations go better when the goal is clear.','What do you want from the conversation?','["To be heard", "To set a boundary", "To apologize", "To ask for help", "To clarify something", "To say no", "To listen"]'::jsonb,'What do you want to remember about what helps?','["Write one sentence first", "Choose the right time", "Stay brief", "Pause if emotions rise", "Bring support if appropriate"]'::jsonb,ARRAY['Counseling','Client Education','Treatment Planning']::text[],true),
(59,'build','daily',null,'My Relapse Warning Signs','Relapse often starts before substance use. Earlier signs deserve attention.','Which sign is most important for you?','["Isolation", "Skipping support", "Romanticizing use", "Contacting risky people", "Poor sleep", "Anger", "Secrets", "Giving up routines", "Feeling hopeless"]'::jsonb,'What do you want to remember about what helps?','["Tell someone today", "Return to support", "Reduce access", "Increase structure", "Ask for professional help"]'::jsonb,ARRAY['Counseling','Client Education','Treatment Planning']::text[],true),
(60,'build','daily',null,'60-Day Review: Stronger Foundations','Two months gives you something important: experience with your own recovery.','What have you learned about staying steady?','["I need support", "Routine matters", "Triggers are predictable", "Cravings pass", "Boundaries help", "Sleep matters", "I need professional care", "I can recover after hard days"]'::jsonb,'What do you want to remember about what helps?','["Choose one Phase 3 priority", "Keep one strong habit", "Review warning signs", "Mark the milestone", "Ask for help with one unfinished need"]'::jsonb,ARRAY['Counseling','Client Education','Treatment Planning']::text[],true),
(61,'understand','daily',null,'Understand My Patterns','Recovery gets stronger when you begin to recognize repeating patterns, not just individual events.','Which pattern keeps showing up?','["Conflict then craving", "Stress then isolation", "Loneliness then risky contact", "Boredom then romanticizing", "Shame then hiding", "Payday then access", "Poor sleep then impulsivity"]'::jsonb,'What pattern or need are you noticing?','["Write down the pattern", "Name the earliest step", "Interrupt it earlier next time", "Tell someone the pattern"]'::jsonb,ARRAY['Assessment','Counseling']::text[],true),
(62,'understand','daily',null,'Thoughts, Feelings, Actions','Thoughts, feelings, and actions influence each other. You can intervene at more than one point.','Where do you notice the cycle most clearly?','["My thoughts", "My emotions", "My body", "My behavior", "My relationships", "I am not sure yet"]'::jsonb,'What pattern or need are you noticing?','["Pause at one point in the cycle", "Write it out", "Use grounding", "Choose a different action"]'::jsonb,ARRAY['Assessment','Counseling']::text[],true),
(63,'understand','daily',null,'What Am I Avoiding?','Avoidance can reduce discomfort briefly while making problems larger later.','What are you most tempted to avoid?','["A conversation", "Money", "Work", "Health", "Family", "Feelings", "Legal issues", "Recovery support"]'::jsonb,'What pattern or need are you noticing?','["Take one small step toward it", "Ask for help", "Schedule it", "Write down the next action only"]'::jsonb,ARRAY['Assessment','Counseling']::text[],true),
(64,'understand','daily',null,'Honesty With Myself','Recovery honesty starts with noticing what is true without immediately defending or judging it.','What is hardest to admit to yourself?','["I need help", "I am angry", "I am scared", "I miss using", "A relationship is unhealthy", "I am exhausted", "I made a mistake", "I do not know what I want"]'::jsonb,'What pattern or need are you noticing?','["Write one honest sentence", "Tell one safe person", "Ask for guidance", "Avoid making a big decision today"]'::jsonb,ARRAY['Assessment','Counseling']::text[],true),
(65,'understand','daily',null,'Self-Respect in Recovery','Self-respect grows through choices that align with your values.','What choice would help you respect yourself tonight?','["Keep a boundary", "Tell the truth", "Go to support", "Take care of my body", "Do one responsibility", "Avoid a risky situation", "Rest"]'::jsonb,'What pattern or need are you noticing?','["Choose one self-respecting action", "Keep it small", "Notice how it feels afterward"]'::jsonb,ARRAY['Assessment','Counseling']::text[],true),
(66,'understand','daily',null,'Shame vs Accountability','Accountability says a behavior needs attention. Shame says you are the problem.','Which response would be healthier today?','["Own what happened", "Make a correction", "Ask for help", "Stop repeating the behavior", "Give someone space", "Practice self-compassion"]'::jsonb,'What pattern or need are you noticing?','["Take responsibility without attacking yourself", "Choose one repair action", "Ask what is appropriate"]'::jsonb,ARRAY['Assessment','Counseling']::text[],true),
(67,'understand','daily',null,'Week 9 Review: What Am I Learning About Me?','Understanding yourself is part of building a recovery that fits your real life.','What have you learned recently?','["My triggers", "My limits", "My emotions", "My strengths", "My support needs", "My boundaries", "My values", "My warning signs"]'::jsonb,'What pattern or need are you noticing?','["Write one lesson", "Share it with someone", "Use it to adjust your recovery plan"]'::jsonb,ARRAY['Assessment','Counseling']::text[],true),
(68,'understand','daily',null,'Relationship Patterns','Relationships can reveal patterns that matter in recovery.','What relationship pattern do you notice?','["People-pleasing", "Avoiding conflict", "Controlling", "Withdrawing", "Choosing chaos", "Weak boundaries", "Fear of abandonment", "Over-dependence"]'::jsonb,'What pattern or need are you noticing?','["Notice it without fixing everything", "Set one boundary", "Ask for support", "Choose one different response"]'::jsonb,ARRAY['Assessment','Counseling']::text[],true),
(69,'understand','daily',null,'Attachment to Old Identity','Sometimes recovery means letting go of an identity that once felt familiar.','What old identity is hardest to release?','["The party person", "The tough one", "The one who needs nobody", "The rescuer", "The rebel", "The victim", "The person who always says yes", "I am not sure"]'::jsonb,'What pattern or need are you noticing?','["Name what no longer fits", "Choose one new identity statement", "Take one action that matches who you are becoming"]'::jsonb,ARRAY['Assessment','Counseling']::text[],true),
(70,'understand','daily',null,'What Do I Believe About Myself?','Beliefs about yourself can shape choices even when you do not notice them.','Which belief gets in your way most?','["I am not enough", "I always fail", "People leave", "I cannot handle stress", "I need substances to cope", "I do not deserve good things", "I have to do everything alone"]'::jsonb,'What pattern or need are you noticing?','["Question the belief", "Find one piece of evidence against it", "Tell someone what you are working on"]'::jsonb,ARRAY['Assessment','Counseling']::text[],true),
(71,'understand','daily',null,'Learning to Trust Yourself','Trust in yourself grows by keeping small promises consistently.','What promise can you realistically keep today?','["Attend support", "Go to bed on time", "Avoid a risky person", "Complete one task", "Tell the truth", "Eat / hydrate", "Ask for help"]'::jsonb,'What pattern or need are you noticing?','["Keep one small promise", "Do not add extra promises", "Notice the result"]'::jsonb,ARRAY['Assessment','Counseling']::text[],true),
(72,'understand','daily',null,'When I Feel Rejected','Rejection can activate old coping patterns quickly.','What do you usually do when you feel rejected?','["Shut down", "Get angry", "Chase reassurance", "Use / crave", "Isolate", "Attack myself", "Contact risky people"]'::jsonb,'What pattern or need are you noticing?','["Pause before reacting", "Name the feeling", "Contact safe support", "Avoid impulsive messages", "Wait before deciding"]'::jsonb,ARRAY['Assessment','Counseling']::text[],true),
(73,'understand','daily',null,'When I Feel Powerless','Substance use can become a way to escape helplessness. Recovery can build other ways to respond.','Where do you feel least in control?','["Family", "Work", "Money", "Health", "Legal issues", "Relationships", "Other people''s choices", "My emotions"]'::jsonb,'What pattern or need are you noticing?','["Choose one controllable action", "Ask for help", "Set one boundary", "Let go of one uncontrollable thing"]'::jsonb,ARRAY['Assessment','Counseling']::text[],true),
(74,'understand','daily',null,'Week 10 Review: Patterns & Choices','The point of seeing patterns is not to judge yourself. It is to create more choice.','Which pattern are you interrupting more often?','["Isolation", "Impulsivity", "Conflict", "Avoidance", "People-pleasing", "Risky contact", "Poor routine", "Hiding"]'::jsonb,'What pattern or need are you noticing?','["Keep practicing one interruption", "Tell someone what is changing", "Plan for the next time the pattern appears"]'::jsonb,ARRAY['Assessment','Counseling']::text[],true),
(75,'understand','daily',null,'Family Roles','Families often develop roles during addiction. Recovery may change those roles.','Which role feels familiar?','["Caretaker", "Peacemaker", "Scapegoat", "Hero", "Invisible one", "Controller", "Dependent one", "I am not sure"]'::jsonb,'What pattern or need are you noticing?','["Notice the role", "Choose one healthier response", "Avoid taking responsibility for everyone"]'::jsonb,ARRAY['Assessment','Counseling']::text[],true),
(76,'understand','daily',null,'Responsibility Without Overload','Taking responsibility does not mean carrying everything at once.','What responsibility actually belongs to you today?','["My recovery", "My words", "My money choices", "My work", "My parenting", "My appointments", "My boundaries"]'::jsonb,'What pattern or need are you noticing?','["Handle one responsibility", "Let go of one that is not yours", "Ask for help where appropriate"]'::jsonb,ARRAY['Assessment','Counseling']::text[],true),
(77,'understand','daily',null,'Communication: Say What You Mean','Clear communication reduces guessing and resentment.','What do you need to communicate more clearly?','["I need help", "I need space", "I am not comfortable", "I cannot do that", "I am sorry", "I need more time", "I disagree"]'::jsonb,'What pattern or need are you noticing?','["Practice one clear sentence", "Avoid over-explaining", "Choose the right time", "Listen after speaking"]'::jsonb,ARRAY['Assessment','Counseling']::text[],true),
(78,'understand','daily',null,'Listening Without Defending','Sometimes recovery means hearing how others were affected without immediately arguing your side.','What makes listening difficult?','["Shame", "Anger", "Feeling misunderstood", "Fear of blame", "Wanting to fix it", "Feeling attacked"]'::jsonb,'What pattern or need are you noticing?','["Listen for two minutes", "Ask one question", "Take a break if flooded", "Return later"]'::jsonb,ARRAY['Assessment','Counseling']::text[],true),
(79,'understand','daily',null,'Making Amends Carefully','Repair should be thoughtful, safe, and appropriate—not rushed.','What matters most before making an amends?','["Stability", "Timing", "Safety", "Guidance", "No hidden expectation", "Respecting boundaries", "Being ready for any response"]'::jsonb,'What pattern or need are you noticing?','["Ask for guidance", "Wait if needed", "Focus on changed behavior", "Do not force contact"]'::jsonb,ARRAY['Assessment','Counseling']::text[],true),
(80,'understand','daily',null,'Forgiveness & Recovery','Forgiveness can mean different things and does not require removing healthy boundaries.','What feels most important around forgiveness?','["Forgiving myself", "Letting go of resentment", "Keeping boundaries", "Accepting what happened", "Not rushing", "Getting support"]'::jsonb,'What pattern or need are you noticing?','["Write one reflection", "Talk to someone safe", "Keep the boundary", "Allow the process to take time"]'::jsonb,ARRAY['Assessment','Counseling']::text[],true),
(81,'understand','daily',null,'Week 11 Review: Relationships','Relationships often change as recovery changes.','What relationship skill are you practicing most?','["Boundaries", "Honesty", "Listening", "Patience", "Asking for help", "Saying no", "Repair", "Giving space"]'::jsonb,'What pattern or need are you noticing?','["Practice it once today", "Notice what happens", "Ask for feedback from someone safe"]'::jsonb,ARRAY['Assessment','Counseling']::text[],true),
(82,'understand','daily',null,'Work, Purpose & Identity','Recovery can create space to think about what kind of life you want to build.','What do you want work or purpose to give you?','["Stability", "Meaning", "Income", "Structure", "Growth", "Service", "Confidence", "Independence"]'::jsonb,'What pattern or need are you noticing?','["Take one work / purpose step", "Update one goal", "Ask someone for guidance", "Do one task"]'::jsonb,ARRAY['Assessment','Counseling']::text[],true),
(83,'understand','daily',null,'Money & Values','Money choices can reflect both risk and values.','What value do you want your money choices to support?','["Stability", "Family", "Independence", "Responsibility", "Health", "Future goals", "Generosity", "Safety"]'::jsonb,'What pattern or need are you noticing?','["Make one value-based money choice", "Plan one expense", "Avoid one risky purchase", "Ask for financial help"]'::jsonb,ARRAY['Assessment','Counseling']::text[],true),
(84,'understand','daily',null,'Health as Part of Recovery','Recovery includes caring for the body, not only avoiding substances.','What health area needs attention?','["Sleep", "Nutrition", "Movement", "Dental care", "Medication", "Medical appointment", "Mental health", "Pain"]'::jsonb,'What pattern or need are you noticing?','["Schedule one appointment", "Take prescribed medication", "Eat / hydrate", "Move gently", "Rest"]'::jsonb,ARRAY['Assessment','Counseling']::text[],true),
(85,'understand','daily',null,'Fun Without Using','Recovery needs room for enjoyment, not just responsibility.','What sounds enjoyable without substances?','["Music", "Food", "Movies", "Games", "Outdoors", "Sports", "Art", "Friends", "Travel", "Learning"]'::jsonb,'What pattern or need are you noticing?','["Plan one enjoyable activity", "Try something new", "Invite a safe person"]'::jsonb,ARRAY['Assessment','Counseling']::text[],true),
(86,'understand','daily',null,'Spirituality, Meaning or Values','People find meaning in different ways. Lellee can support the path that fits you.','What gives your life meaning right now?','["Faith", "Family", "Service", "Nature", "Creativity", "Learning", "Community", "Recovery itself", "My values", "I am still exploring"]'::jsonb,'What pattern or need are you noticing?','["Spend time with what matters", "Write one reflection", "Connect with a community", "Take one values-based action"]'::jsonb,ARRAY['Assessment','Counseling']::text[],true),
(87,'understand','daily',null,'Giving Back Without Losing Yourself','Helping others can support recovery, but not when it replaces caring for yourself.','What kind of service feels healthy?','["Encouragement", "Helping at a meeting", "Family help", "Community service", "Mentoring later", "Faith community", "Small acts of kindness"]'::jsonb,'What pattern or need are you noticing?','["Do one small act", "Keep your boundary", "Do not overcommit", "Make sure your own recovery comes first"]'::jsonb,ARRAY['Assessment','Counseling']::text[],true),
(88,'understand','daily',null,'Week 12 Review: Who Am I Becoming?','Recovery can slowly change how you see yourself.','Which quality feels stronger now?','["Honesty", "Patience", "Courage", "Responsibility", "Compassion", "Boundaries", "Hope", "Self-respect"]'::jsonb,'What pattern or need are you noticing?','["Choose one quality to keep practicing", "Write how it has changed", "Ask someone what they notice"]'::jsonb,ARRAY['Assessment','Counseling']::text[],true),
(89,'understand','daily',null,'My Recovery Identity','You are more than your substance use history.','Which statement feels closest today?','["I am learning", "I am rebuilding", "I am becoming more honest", "I am stronger than I thought", "I still need support", "I am allowed to change", "Recovery is part of my life, not all of me"]'::jsonb,'What pattern or need are you noticing?','["Choose one identity statement", "Take one action that supports it", "Save it for Then & Now"]'::jsonb,ARRAY['Assessment','Counseling']::text[],true),
(90,'understand','daily',null,'90-Day Review: Understanding Myself','Ninety days gives you a clearer picture of your patterns, strengths, risks, and values.','What have you learned most about yourself?','["My triggers", "My emotions", "My relationship patterns", "My strengths", "My warning signs", "My values", "My support needs", "My ability to change"]'::jsonb,'What pattern or need are you noticing?','["Choose one Month 4 priority", "Review Then & Now", "Keep one core support", "Celebrate the milestone", "Ask for help with one unfinished need"]'::jsonb,ARRAY['Assessment','Counseling']::text[],true),
