-- LELLEE BIG BUILD A — CORE PRODUCT COMPLETION
-- Full Recovery Content + Tools/Coping Center + Personalization.
begin;

create or replace function public.set_updated_at()
returns trigger language plpgsql as $$
begin new.updated_at=now(); return new; end $$;

alter table if exists public.guided_responses add column if not exists metadata jsonb not null default '{}'::jsonb;
create unique index if not exists uq_guided_response_day_prompt on public.guided_responses(user_id,response_date,prompt_key);

-- Journal compatibility carried forward from the prior build.
create table if not exists public.journal_collections(
 id uuid primary key default gen_random_uuid(),
 user_id uuid not null references auth.users(id) on delete cascade,
 name text not null, description text, system_key text, sort_order integer not null default 100,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 unique(user_id,name)
);
alter table if exists public.journal_entries
 add column if not exists collection_id uuid references public.journal_collections(id) on delete set null,
 add column if not exists source text not null default 'digital',
 add column if not exists physical_volume text,
 add column if not exists physical_page text,
 add column if not exists tags text[] not null default '{}',
 add column if not exists allow_recovery_story boolean not null default false;

create table if not exists public.journey_content(
 id uuid primary key default gen_random_uuid(),
 day_number integer unique,
 phase_key text not null,
 cadence text not null default 'daily',
 cadence_index integer,
 title text not null,
 summary text,
 prompt text not null,
 choices jsonb not null default '[]'::jsonb,
 reflection_prompt text,
 actions jsonb not null default '[]'::jsonb,
 tap21_domains text[] not null default '{}',
 published boolean not null default true,
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now()
);
create unique index if not exists uq_journey_longterm on public.journey_content(phase_key,cadence_index) where phase_key='long_term';

create table if not exists public.recovery_tools(
 id uuid primary key default gen_random_uuid(), slug text not null unique, title text not null,
 category text not null, summary text, steps jsonb not null default '[]'::jsonb,
 recommended_for text[] not null default '{}', symbol text, is_safety_adjacent boolean not null default false,
 published boolean not null default true, sort_order integer not null default 100,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.tool_use_log(
 id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade,
 tool_slug text not null, started_at timestamptz not null default now(), completed_at timestamptz,
 metadata jsonb not null default '{}'::jsonb
);
create table if not exists public.personalization_preferences(
 user_id uuid primary key references auth.users(id) on delete cascade,
 enabled boolean not null default true,
 recommendation_style text not null default 'gentle' check(recommendation_style in('gentle','practical','reflective')),
 belief_variants boolean not null default true,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);

alter table if exists public.content_items
 add column if not exists tags text[] not null default '{}',
 add column if not exists tap21_domains text[] not null default '{}',
 add column if not exists printable boolean not null default false;
create table if not exists public.saved_learning(
 id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade,
 content_item_id uuid not null references public.content_items(id) on delete cascade,
 created_at timestamptz not null default now(), unique(user_id,content_item_id)
);
create table if not exists public.learning_progress(
 id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade,
 content_item_id uuid not null references public.content_items(id) on delete cascade,
 status text not null default 'started', completed_at timestamptz,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 unique(user_id,content_item_id)
);

alter table public.journal_collections enable row level security;
alter table public.journey_content enable row level security;
alter table public.recovery_tools enable row level security;
alter table public.tool_use_log enable row level security;
alter table public.personalization_preferences enable row level security;
alter table public.saved_learning enable row level security;
alter table public.learning_progress enable row level security;

drop policy if exists "journal_collections_own" on public.journal_collections;
create policy "journal_collections_own" on public.journal_collections for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
drop policy if exists "journey_content_read" on public.journey_content;
create policy "journey_content_read" on public.journey_content for select to anon,authenticated using(published=true);
drop policy if exists "recovery_tools_read" on public.recovery_tools;
create policy "recovery_tools_read" on public.recovery_tools for select to anon,authenticated using(published=true);
drop policy if exists "tool_use_log_own" on public.tool_use_log;
create policy "tool_use_log_own" on public.tool_use_log for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
drop policy if exists "personalization_preferences_own" on public.personalization_preferences;
create policy "personalization_preferences_own" on public.personalization_preferences for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
drop policy if exists "saved_learning_own" on public.saved_learning;
create policy "saved_learning_own" on public.saved_learning for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
drop policy if exists "learning_progress_own" on public.learning_progress;
create policy "learning_progress_own" on public.learning_progress for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);

grant select on public.journey_content,public.recovery_tools to anon,authenticated;
grant select,insert,update,delete on public.journal_collections,public.tool_use_log,public.personalization_preferences,public.saved_learning,public.learning_progress to authenticated;

drop trigger if exists set_updated_at on public.journal_collections;
create trigger set_updated_at before update on public.journal_collections for each row execute function public.set_updated_at();
drop trigger if exists set_updated_at on public.journey_content;
create trigger set_updated_at before update on public.journey_content for each row execute function public.set_updated_at();
drop trigger if exists set_updated_at on public.recovery_tools;
create trigger set_updated_at before update on public.recovery_tools for each row execute function public.set_updated_at();
drop trigger if exists set_updated_at on public.personalization_preferences;
create trigger set_updated_at before update on public.personalization_preferences for each row execute function public.set_updated_at();
drop trigger if exists set_updated_at on public.learning_progress;
create trigger set_updated_at before update on public.learning_progress for each row execute function public.set_updated_at();

commit;

