values(null,'long_term','weekly',5,'Health Check','Physical and mental health can affect recovery long after early stabilization.','What health area deserves attention?','["Sleep", "Movement", "Nutrition", "Medical care", "Mental health", "Medication", "Stress", "Dental care"]'::jsonb,'What do you want to carry into the next week?','["Make an appointment", "Protect rest", "Move my body", "Prepare food", "Talk with a clinician"]'::jsonb,ARRAY['Relapse Prevention','Client Education']::text[],true)
