values(null,'long_term','weekly',6,'Relationship Check','Established recovery can reveal new relationship work.','What relationship pattern deserves attention?','["Communication", "Trust", "Boundaries", "Conflict", "Intimacy", "Family roles", "Friendship", "Independence"]'::jsonb,'What do you want to carry into the next week?','["Have one clear conversation", "Set a boundary", "Listen", "Repair one thing", "Seek counseling"]'::jsonb,ARRAY['Relapse Prevention','Client Education']::text[],true)
