values(null,'long_term','weekly',7,'Money & Stability','Financial stress can affect recovery even years later.','What money or stability issue needs a small next step?','["Budget", "Debt", "Benefits", "Work", "Housing", "Savings", "Taxes", "No urgent issue"]'::jsonb,'What do you want to carry into the next week?','["Review one account", "Make one call", "Set a budget step", "Ask for help", "Schedule paperwork time"]'::jsonb,ARRAY['Relapse Prevention','Client Education']::text[],true)
