values(null,'long_term','weekly',8,'Joy & Enjoyment','A durable recovery life needs enjoyment, not only responsibility.','What kind of healthy enjoyment is missing?','["Rest", "Adventure", "Friends", "Music", "Food", "Nature", "Creativity", "Travel", "Quiet"]'::jsonb,'What do you want to carry into the next week?','["Plan something enjoyable", "Invite someone", "Spend time outside", "Create something", "Rest"]'::jsonb,ARRAY['Relapse Prevention','Client Education']::text[],true)
