values(null,'long_term','weekly',9,'Warning Signs','Long-term warning signs can be subtle.','What deserves respect this week?','["Isolation", "Resentment", "Poor sleep", "Overwork", "Skipping support", "Secrecy", "Risky nostalgia", "Nothing concerning"]'::jsonb,'What do you want to carry into the next week?','["Tell someone", "Restart support", "Rest", "Review triggers", "Use a coping tool"]'::jsonb,ARRAY['Relapse Prevention','Client Education']::text[],true)
