values(null,'long_term','weekly',10,'Identity & Growth','Recovery can stay important without becoming your entire identity.','What part of yourself are you growing?','["Parent / family", "Professional", "Student", "Creative", "Friend", "Community member", "Person of faith", "Still exploring"]'::jsonb,'What do you want to carry into the next week?','["Invest one hour", "Set one goal", "Join something", "Learn something", "Reflect"]'::jsonb,ARRAY['Relapse Prevention','Client Education']::text[],true)
