values(null,'long_term','weekly',11,'Giving Back With Boundaries','Helping others can be meaningful without becoming self-neglect.','How are you balancing service and your own recovery?','["Balanced", "Doing too much", "Avoiding my needs", "Want more service", "Need stronger limits"]'::jsonb,'What do you want to carry into the next week?','["Set one boundary", "Ask for help", "Choose one service action", "Rest", "Return focus to my recovery"]'::jsonb,ARRAY['Relapse Prevention','Client Education']::text[],true)
