values(null,'long_term','weekly',12,'Annual Recovery Review','An annual review can show change that daily life hides.','What stands out about the last year?','["Support", "Health", "Relationships", "Purpose", "Work", "Money", "Emotions", "Recovery practices", "Unexpected growth"]'::jsonb,'What do you want to carry into the next week?','["Save a milestone review", "Update my plan", "Celebrate safely", "Set a next-year goal", "Thank someone who helped"]'::jsonb,ARRAY['Relapse Prevention','Client Education']::text[],true)
on conflict (phase_key,cadence_index) where phase_key='long_term'
do update set title=excluded.title,summary=excluded.summary,prompt=excluded.prompt,choices=excluded.choices,reflection_prompt=excluded.reflection_prompt,actions=excluded.actions,updated_at=now();
values('craving-reset','Craving Reset','cravings','Create distance from an urge and protect the next few minutes.','["Name the urge without arguing with it.", "Move away from alcohol, drugs, or a high-risk setting if you can.", "Contact a safe support person before the urge becomes stronger.", "Use water, food, movement, grounding, or a meeting to create time.", "Reassess after the urge has had time to change."]'::jsonb,ARRAY['craving','urge','substance']::text[],'◉',false,true,10)
on conflict(slug) do update set title=excluded.title,category=excluded.category,summary=excluded.summary,steps=excluded.steps,recommended_for=excluded.recommended_for,symbol=excluded.symbol,is_safety_adjacent=excluded.is_safety_adjacent,published=true,sort_order=excluded.sort_order,updated_at=now();
values('urge-surfing','Urge Surfing','cravings','Notice an urge as a changing wave instead of a command.','["Notice where the urge shows up in your body.", "Describe the sensation without fighting it.", "Watch for changes in intensity.", "Keep yourself away from access while the urge rises and falls.", "Use support if the urge is becoming unsafe."]'::jsonb,ARRAY['craving','urge']::text[],'≈',false,true,20)
on conflict(slug) do update set title=excluded.title,category=excluded.category,summary=excluded.summary,steps=excluded.steps,recommended_for=excluded.recommended_for,symbol=excluded.symbol,is_safety_adjacent=excluded.is_safety_adjacent,published=true,sort_order=excluded.sort_order,updated_at=now();
values('grounding-54321','5-4-3-2-1 Grounding','calming','Bring attention back to the present when thoughts or anxiety are racing.','["Name 5 things you can see.", "Name 4 things you can physically feel.", "Name 3 things you can hear.", "Name 2 things you can smell.", "Name 1 thing you can taste or one breath you can notice."]'::jsonb,ARRAY['anxious','overwhelmed','panic']::text[],'◎',false,true,30)
on conflict(slug) do update set title=excluded.title,category=excluded.category,summary=excluded.summary,steps=excluded.steps,recommended_for=excluded.recommended_for,symbol=excluded.symbol,is_safety_adjacent=excluded.is_safety_adjacent,published=true,sort_order=excluded.sort_order,updated_at=now();
values('paced-breathing','Paced Breathing','calming','Use a slower exhale to help your body settle.','["Sit or stand somewhere safe.", "Breathe in gently.", "Let the exhale be a little longer than the inhale.", "Repeat without forcing a very deep breath.", "Stop if breathing exercises make you feel worse and choose another grounding tool."]'::jsonb,ARRAY['stress','angry','overwhelmed']::text[],'≈',false,true,40)
on conflict(slug) do update set title=excluded.title,category=excluded.category,summary=excluded.summary,steps=excluded.steps,recommended_for=excluded.recommended_for,symbol=excluded.symbol,is_safety_adjacent=excluded.is_safety_adjacent,published=true,sort_order=excluded.sort_order,updated_at=now();
values('halt-check','HALT Check','planning','Check whether hunger, anger, loneliness, or tiredness is making recovery harder.','["Ask: am I hungry?", "Ask: am I angry or activated?", "Ask: am I lonely or disconnected?", "Ask: am I tired?", "Meet the most basic need first, then reassess."]'::jsonb,ARRAY['hungry','angry','lonely','tired']::text[],'H',false,true,50)
on conflict(slug) do update set title=excluded.title,category=excluded.category,summary=excluded.summary,steps=excluded.steps,recommended_for=excluded.recommended_for,symbol=excluded.symbol,is_safety_adjacent=excluded.is_safety_adjacent,published=true,sort_order=excluded.sort_order,updated_at=now();
values('trigger-review','Trigger Review','triggers','Study what happened before an urge without blaming yourself.','["What happened just before the urge?", "Who was there?", "What were you feeling or thinking?", "What warning sign showed up first?", "What could create more safety next time?"]'::jsonb,ARRAY['trigger','people','places','conflict']::text[],'↻',false,true,60)
on conflict(slug) do update set title=excluded.title,category=excluded.category,summary=excluded.summary,steps=excluded.steps,recommended_for=excluded.recommended_for,symbol=excluded.symbol,is_safety_adjacent=excluded.is_safety_adjacent,published=true,sort_order=excluded.sort_order,updated_at=now();
values('exit-plan','Exit a High-Risk Situation','cravings','Make leaving easier when substances or risky people are nearby.','["Decide that leaving is allowed even if it feels awkward.", "Move toward a safer location.", "Contact someone who supports your recovery.", "Arrange safe transportation if needed.", "Once safe, decide what support you need next."]'::jsonb,ARRAY['around substances','risky place']::text[],'↗',false,true,70)
on conflict(slug) do update set title=excluded.title,category=excluded.category,summary=excluded.summary,steps=excluded.steps,recommended_for=excluded.recommended_for,symbol=excluded.symbol,is_safety_adjacent=excluded.is_safety_adjacent,published=true,sort_order=excluded.sort_order,updated_at=now();
values('anger-pause','Anger Pause','calming','Create space before saying or doing something that could make things harder.','["Do not send the message or continue the argument yet.", "Move away if it is safe.", "Notice what your body is doing.", "Use grounding, walking, or another calming tool.", "Return only when you can choose your next action."]'::jsonb,ARRAY['angry','conflict']::text[],'!',false,true,80)
on conflict(slug) do update set title=excluded.title,category=excluded.category,summary=excluded.summary,steps=excluded.steps,recommended_for=excluded.recommended_for,symbol=excluded.symbol,is_safety_adjacent=excluded.is_safety_adjacent,published=true,sort_order=excluded.sort_order,updated_at=now();
values('connection-step','Move Toward Connection','connection','Use a small connection step before loneliness becomes isolation.','["Name one safe person or place.", "Choose a low-pressure contact: text, call, meeting, or shared activity.", "Say something simple such as “I could use some company.”", "If one person is unavailable, try another support.", "Do not treat one unavailable person as a reason to isolate."]'::jsonb,ARRAY['lonely','alone','isolating']::text[],'♡',false,true,90)
on conflict(slug) do update set title=excluded.title,category=excluded.category,summary=excluded.summary,steps=excluded.steps,recommended_for=excluded.recommended_for,symbol=excluded.symbol,is_safety_adjacent=excluded.is_safety_adjacent,published=true,sort_order=excluded.sort_order,updated_at=now();
values('sleep-reset','Sleep Reset','sleep','Protect recovery by making tonight a little easier on your body and mind.','["Choose a realistic bedtime window.", "Reduce stimulating screens or conflict close to bedtime.", "Limit late caffeine if it affects you.", "Prepare the room for sleep.", "Discuss persistent or severe sleep problems with a healthcare professional."]'::jsonb,ARRAY['sleep','tired']::text[],'☾',false,true,100)
on conflict(slug) do update set title=excluded.title,category=excluded.category,summary=excluded.summary,steps=excluded.steps,recommended_for=excluded.recommended_for,symbol=excluded.symbol,is_safety_adjacent=excluded.is_safety_adjacent,published=true,sort_order=excluded.sort_order,updated_at=now();
values('boundary-builder','Boundary Builder','relationships','Turn “this is too much” into a clear recovery-protecting boundary.','["Name the situation costing you stability.", "Decide what you will do—not what you will force another person to do.", "Use a short, clear sentence.", "Plan how you will follow through.", "Use support if safety or coercion is involved."]'::jsonb,ARRAY['boundary','relationship','family']::text[],'◇',false,true,110)
on conflict(slug) do update set title=excluded.title,category=excluded.category,summary=excluded.summary,steps=excluded.steps,recommended_for=excluded.recommended_for,symbol=excluded.symbol,is_safety_adjacent=excluded.is_safety_adjacent,published=true,sort_order=excluded.sort_order,updated_at=now();
values('support-script','Ask for Help Script','connection','Make reaching out easier when you do not know what to say.','["Choose a safe person.", "Start with: “I do not need you to fix this.”", "Say what is happening in one sentence.", "Ask for one specific thing.", "If that person cannot help, contact another support."]'::jsonb,ARRAY['support','help','lonely']::text[],'☎',false,true,120)
on conflict(slug) do update set title=excluded.title,category=excluded.category,summary=excluded.summary,steps=excluded.steps,recommended_for=excluded.recommended_for,symbol=excluded.symbol,is_safety_adjacent=excluded.is_safety_adjacent,published=true,sort_order=excluded.sort_order,updated_at=now();
values('warning-sign-plan','Early Warning Plan','planning','Decide what to do when recovery starts drifting before a return to use.','["List your earliest warning signs.", "Choose the first support person you will contact.", "Choose one place or situation you will avoid.", "Name one recovery routine you will restart immediately.", "Include professional or emergency support when needed."]'::jsonb,ARRAY['warning','relapse','drift']::text[],'◆',false,true,130)
on conflict(slug) do update set title=excluded.title,category=excluded.category,summary=excluded.summary,steps=excluded.steps,recommended_for=excluded.recommended_for,symbol=excluded.symbol,is_safety_adjacent=excluded.is_safety_adjacent,published=true,sort_order=excluded.sort_order,updated_at=now();
values('after-use','After a Return to Use','planning','Respond to a return to use with safety and the next appropriate support step.','["Get to a safer environment.", "Do not drive or add substances to “even things out.”", "Contact someone you trust.", "Seek urgent medical help for overdose symptoms, breathing problems, loss of consciousness, severe illness, or other emergencies.", "After immediate safety, reconnect with treatment or recovery support and review what happened without treating it as the end of recovery."]'::jsonb,ARRAY['already used','relapse','return to use']::text[],'↺',true,true,140)
on conflict(slug) do update set title=excluded.title,category=excluded.category,summary=excluded.summary,steps=excluded.steps,recommended_for=excluded.recommended_for,symbol=excluded.symbol,is_safety_adjacent=excluded.is_safety_adjacent,published=true,sort_order=excluded.sort_order,updated_at=now();
values('one-task','One-Task Reset','planning','Reduce overwhelm by shrinking the day to one practical next step.','["Write down what is competing for attention.", "Circle the one thing that most affects safety or stability.", "Break it into a 5–20 minute step.", "Do only that step.", "Reassess after it is complete."]'::jsonb,ARRAY['overwhelmed','money','work','housing']::text[],'1',false,true,150)
