values('meeting-ready','Get Ready for Support','connection','Make attending a meeting, group, or appointment easier.','["Confirm the time and location or link.", "Plan transportation or a quiet place.", "Decide whether to contact someone beforehand.", "Bring one question if useful.", "Afterward, note one thing you want to carry forward."]'::jsonb,ARRAY['meeting','support','treatment']::text[],'▤',false,true,160)
